window.piConnectSession = async function (channel) {
  channel = String(channel || '').toLowerCase();
  var label = channel === 'booking' ? 'Booking.com' : 'Airbnb';
  var raw = prompt(
    'Paste ' + label + ' Playwright storageState JSON (from scripts/platform-invoice-save-session.js).\n' +
    'This is a one-time connect — not a PDF upload. After this, use Pull from portals.'
  );
  if (raw == null) return;
  raw = String(raw).trim();
  if (!raw) return;
  try {
    var state = null;
    if (raw.indexOf('{') === 0) state = JSON.parse(raw);
    else {
      try { state = JSON.parse(atob(raw.replace(/^.*?=/, ''))); }
      catch (e2) { state = JSON.parse(atob(raw)); }
    }
    var res = await fetch('/api/platform-invoices/sessions/' + encodeURIComponent(channel), {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ storageState: state })
    });
    var j = await res.json();
    if (!res.ok || !j.ok) throw new Error((j && j.error) || 'connect failed');
    msg(label + ' connected — running Pull…', true);
    await piReload();
    await piPull();
  } catch (e) { msg(e.message || String(e), false); }
};

