window.piParseSessionPayload = function (raw) {
  raw = String(raw || '').trim();
  if (!raw) throw new Error('Empty session');
  if (raw.indexOf('{') === 0) return JSON.parse(raw);
  var cleaned = raw.replace(/^\s*[A-Z_]*STORAGE_STATE_B64=/, '').replace(/\s+/g, '');
  return JSON.parse(atob(cleaned));
};
window.piSaveSessionState = async function (channel, state) {
  var res = await fetch('/api/platform-invoices/sessions/' + encodeURIComponent(channel), {
    method: 'PUT', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ storageState: state })
  });
  var j = await res.json();
  if (!res.ok || !j.ok) throw new Error((j && j.error) || 'connect failed');
  return j;
};
window.piConnectSession = async function (channel) {
  channel = String(channel || '').toLowerCase();
  var label = channel === 'booking' ? 'Booking.com' : 'Airbnb';
  var inp = document.getElementById(channel === 'booking' ? 'pi-session-file-booking' : 'pi-session-file-airbnb');
  if (inp) {
    inp.value = '';
    inp.onchange = function () {
      var file = inp.files && inp.files[0];
      if (!file) return;
      var reader = new FileReader();
      reader.onload = function () {
        piConnectSessionFromText(channel, String(reader.result || '')).catch(function (e) {
          msg(e.message || String(e), false);
        });
      };
      reader.onerror = function () { msg('Could not read session file', false); };
      reader.readAsText(file);
    };
    inp.click();
    return;
  }
  var raw = prompt(
    'Paste ' + label + ' storageState JSON or STORAGE_STATE_B64 line\n' +
    '(from platform-invoice-save-session.js). One-time connect — not a PDF.'
  );
  if (raw == null || !String(raw).trim()) return;
  try { await piConnectSessionFromText(channel, raw); }
  catch (e) { msg(e.message || String(e), false); }
};
window.piConnectSessionFromText = async function (channel, raw) {
  var label = channel === 'booking' ? 'Booking.com' : 'Airbnb';
  var state = piParseSessionPayload(raw);
  await piSaveSessionState(channel, state);
  msg(label + ' session saved — pulling…', true);
  await piReload();
  await piPull();
};

