window.piPull = async function (opts) {
  opts = opts || {};
  var month = monthVal();
  var btn = document.getElementById('pi-pull-btn');
  if (btn) btn.disabled = true;
  msg('Pulling from portals (can take several minutes)…', true);
  try {
    var apts = ((PI.health && PI.health.bdcApts) || []).map(function (a) {
      return { aptId: a.aptId || '', aptName: a.aptName || '' };
    });
    if (!apts.length && typeof S !== 'undefined' && Array.isArray(S.apts)) {
      apts = S.apts.map(function (a) { return { aptId: a.id || a.aptId || '', aptName: a.name || a.aptName || '' }; });
    }
    var body = { month: month, channel: opts.channel || 'all', apartments: apts };
    if (opts.airbnbOtp) body.airbnbOtp = String(opts.airbnbOtp);
    var res = await fetch('/api/platform-invoices/pull', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    var r = await res.json();
    var errs = r.errors || [];
    var errTxt = errs.map(function (e) {
      return (e.channel ? (e.channel + ': ') : '') + (e.property ? (e.property + ' — ') : '') + (e.error || e.hint || '');
    }).filter(Boolean).slice(0, 4).join(' · ');
    var blob = errTxt + ' ' + (r.error || '') + ' ' + (r.hint || '');
    var needsAirbnbOtp = /OTP|confirmation code|one-time/i.test(blob) && /airbnb/i.test(blob);
    var needsBookingSession = /captcha|human|Connect Booking|reconnect Booking/i.test(blob);
    var needsAirbnbSession = /Connect a saved host session|reconnect Airbnb|session expired/i.test(blob) && /airbnb/i.test(blob);

    if (!res.ok) {
      if (needsAirbnbOtp && !opts.airbnbOtp && !opts._otpTried) {
        var code = prompt('Airbnb emailed/SMS’d a login code. Enter the OTP to finish this pull (or Cancel and use Connect Airbnb with a saved session):');
        if (code && String(code).trim()) {
          await piPull({ airbnbOtp: String(code).trim(), _otpTried: true, channel: 'airbnb' });
          // also try booking if still needed
          if (!(PI.status && PI.status.bookingSession && PI.status.bookingSession.connected)) {
            msg('Airbnb OTP submitted. Connect Booking session (captcha cannot be solved on the server), then Pull again.', false);
          }
          return;
        }
      }
      throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (errTxt ? (' · ' + errTxt) : ''));
    }
    var n = (r.saved || []).length;
    if (n === 0) {
      if (needsAirbnbOtp && !opts.airbnbOtp && !opts._otpTried) {
        var code2 = prompt('Airbnb asked for OTP and saved 0 PDFs. Paste the code from email/SMS to retry Airbnb now:');
        if (code2 && String(code2).trim()) {
          await piPull({ airbnbOtp: String(code2).trim(), _otpTried: true, channel: 'airbnb' });
          return;
        }
      }
      var next = '';
      if (needsBookingSession) next += ' → Connect Booking (upload session .json from headed login).';
      if (needsAirbnbSession || needsAirbnbOtp) next += ' → Connect Airbnb (or enter OTP when prompted).';
      msg('Automated pull saved 0 PDFs' + (errTxt ? (' — ' + errTxt) : '') + next, false);
    } else {
      msg('Pulled ' + n + ' PDF(s) automatically' + (errTxt ? (' · notes: ' + errTxt) : ''), true);
    }
    await piHealth();
    await piReload();
  } catch (e) { msg(e.message || String(e), false); }
  finally { if (btn) btn.disabled = false; }
};
